<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {missingReason} from '../../api/business-messages'
import {useUnsaved} from '../../composables/useUnsaved'
import type {components} from '@adc/contracts'
import {createProtectedClient} from '../../api/protected'
import {ApiFailure,prepareCommand,UnknownOutcomeError,type PreparedCommand} from '../../api/http'
import {useAuthenticationStore} from '../../stores/authentication'
type Performance=components['schemas']['PerformanceView']&{cutoff?:string;clinic_ids?:string[]};type Closure={clinic_id:string;source_reference:string;verification_reference:string;zero_cost_scope:string[]}
interface Snapshot {input:{personnel:{id:string;hire:string;termination:string|null}[];revenue:{item:string;dentist:string;clinic:string;amount:string;issued:string}[];costs:{id:string;dentist:string|null;clinic:string;type:string;amount:string;source:string;incurred:string}[];closures:{clinic:string;source:string;verification:string;zeroScopes:string[]}[]};allocations:{clinic_id:string;net_amount:string;recipients:{dentist_id:string;normal_minutes:string;share:string}[]}[]}
const statusName:Record<string,string>={DRAFT:'准备中',INCOMPLETE:'资料不全',CALCULATED:'已计算，待复核',PUBLISHED:'已发布',SUPERSEDED:'已替换（历史）'}
const api=createProtectedClient(),auth=useAuthenticationStore(),can=(cap:string)=>auth.canAccess('HEADQUARTERS',cap),sourceAllowed=computed(()=>['sensitive.drilldown','cost.verify','getInvoice','resource.read'].every(can)),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref(''),items=ref<Performance[]>([]),next=ref<string|null>(null),sources=ref<components['schemas']['PerformanceSource']|null>(null),closures=ref<Closure[]>([]),clinicText=ref(''),personnel=ref(''),preparationText=ref(''),reviewReference=ref(''),reviewed=ref<string[]>([]),confirmed=ref(false)
const today=new Date(),quarterMonth=Math.floor((Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',month:'numeric'}).format(today))-1)/3)*3,year=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',year:'numeric'}).format(today)),end=new Date(Date.UTC(year,quarterMonth,1)),start=new Date(Date.UTC(year,quarterMonth-3,1)),period=ref({quarter_start:start.toISOString().slice(0,10),quarter_end:end.toISOString().slice(0,10),cutoff:today.toISOString()})
const stage=ref(1),clinicOptions=ref<{id:string;label:string}[]>([]),selectedClinics=ref<string[]>([]),selectedBatch=ref('')
const batches=computed(()=>[...new Map(items.value.filter(r=>r.cutoff&&r.calculation_status==='DRAFT').map(r=>[r.input_hash,r])).values()])
const quarterOptions=Array.from({length:8},(_,i)=>{const d=new Date(Date.UTC(year,quarterMonth-3-i*3,1));return {value:d.toISOString().slice(0,10),label:d.getUTCFullYear()+' 年第 '+(Math.floor(d.getUTCMonth()/3)+1)+' 季度'}})
function changeQuarter(){const d=new Date(period.value.quarter_start+'T00:00:00Z');period.value.quarter_end=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+3,1)).toISOString().slice(0,10);resetPreparation();stage.value=1;load()}
function bindBatch(){const batch=batches.value.find(r=>r.input_hash===selectedBatch.value);if(!batch)return;period.value.cutoff=batch.cutoff!;selectedClinics.value=batch.clinic_ids??[];clinicText.value=selectedClinics.value.join(',');synchronize();preparationText.value=items.value.filter(r=>r.input_hash===batch.input_hash).map(r=>r.quarterly_performance_id).join(',');stage.value=2}
const preparationBaseline=ref('')
function preparationState(){return JSON.stringify({personnel:personnel.value,closures:closures.value})}
useUnsaved(()=>!!preparationBaseline.value&&preparationBaseline.value!==preparationState(),()=>unknown.value)
let pending:PreparedCommand|undefined,pendingKind:'prepare'|'calculate'|'publish'='calculate'
const snapshot=computed(()=>sources.value?.source_snapshot as unknown as Snapshot|undefined)
function ids(value:string){return [...new Set(value.split(/[\s,，]+/).filter(Boolean))]}
function synchronize(){const existing=new Map(closures.value.map(row=>[row.clinic_id,row]));closures.value=ids(clinicText.value).map(id=>existing.get(id)??{clinic_id:id,source_reference:'',verification_reference:'',zero_cost_scope:[]});confirmed.value=false;preparationText.value=''}
function resetPreparation(){confirmed.value=false;preparationText.value='';sources.value=null}
async function failed(failure:unknown){error.value=failure instanceof ApiFailure?({PERFORMANCE_NOT_PUBLISHABLE:'结果尚不完整或不是可发布计算版本。',INCONSISTENT_PREPARATION_BATCH:'准备凭据、季度、诊所或截止不一致，请核对同一冻结批次。',PERFORMANCE_RECONCILIATION_FAILED:'来源、金额或分摊核验未通过，原发布保持。',CUTOFF_NOT_REPRODUCIBLE:'该历史截止无法重建，请使用新截止重新核实，或读取既有冻结版本。'}[failure.code]??`未完成：${failure.message}`):'服务暂不可用。';if(failure instanceof ApiFailure && [401,403].includes(failure.status)){items.value=[];sources.value=null;reviewed.value=[];await auth.ensure()}}
async function load(more=false){busy.value=true;error.value='';if(!more)items.value=[];try{const query=new URLSearchParams({quarter_start:period.value.quarter_start,quarter_end:period.value.quarter_end,limit:'100'});if(more && next.value)query.set('cursor',next.value);const result=await api.get<{items:Performance[];next_cursor:string|null}>(`/api/v1/quarterly-performances?${query}`);items.value=more?[...items.value,...result.items]:result.items;next.value=result.next_cursor}catch(failure){await failed(failure)}finally{busy.value=false}}
async function execute(){if(!pending)return;busy.value=true;error.value='';try{const result=await api.execute<{items:Performance[]}|Performance>(pending);if('items' in result.data){items.value=result.data.items;next.value=null;if(pendingKind==='prepare'){preparationText.value=result.data.items.map(row=>row.quarterly_performance_id).join(', ');preparationBaseline.value=preparationState()}}else{const row=result.data;items.value=items.value.map(old=>old.quarterly_performance_id===row.quarterly_performance_id?row:old);await load()}notice.value=pendingKind==='prepare'?'准备依据已冻结；请核对系统人员及缺项，再单独计算。':pendingKind==='calculate'?'计算完成；有缺项的版本不可发布，计算不会自动发布。':'独立复核发布完成；原版本保留。';stage.value=pendingKind==='prepare'?2:pendingKind==='calculate'?3:4;pending=undefined;unknown.value=false;confirmed.value=false;reviewed.value=[]}catch(failure){if(failure instanceof UnknownOutcomeError){unknown.value=true;error.value='结果确认中，请保留当前页面并重新确认办理结果。'}else{pending=undefined;unknown.value=false;await failed(failure)}}finally{busy.value=false}}
async function prepare(){if(pending || !confirmed.value)return;pendingKind='prepare';pending=prepareCommand('prepareQuarterPerformance','POST','/api/v1/performance-preparations',{...period.value,clinic_ids:ids(clinicText.value),closure_evidence:closures.value,personnel_verification_reference:personnel.value});await execute()}
async function calculate(){if(pending||!preparationText.value)return;pendingKind='calculate';pending=prepareCommand('calculateQuarterPerformance','POST','/api/v1/performance-calculations',{...period.value,clinic_ids:ids(clinicText.value),preparation_ids:ids(preparationText.value)});await execute()}
async function publish(row:Performance){if(pending || !reviewed.value.includes(row.quarterly_performance_id) || !reviewReference.value.trim())return;pendingKind='publish';pending=prepareCommand('publishQuarterPerformance','POST',`/api/v1/quarterly-performances/${row.quarterly_performance_id}/publish`,{expected_input_hash:row.input_hash,review_reference:reviewReference.value});await execute()}
async function source(row:Performance){sources.value=null;error.value='';try{sources.value=await api.get(`/api/v1/quarterly-performances/${row.quarterly_performance_id}/sources`)}catch(failure){await failed(failure)}}
async function query(){if(!pending)return;try{const result=await api.requestResult<{status:string}>(pending);notice.value=result.status==='SUCCEEDED'?'原请求已成功，请重新确认读取同一结果。':'尚未确认成功，请保留当前页面。'}catch(failure){await failed(failure)}}
onMounted(async()=>{try{let cursor:string|null=null;do{const result:{items:{id:string;label:string}[];next_cursor:string|null}=await api.get('/api/v1/clinics?limit=100'+(cursor?'&cursor='+encodeURIComponent(cursor):''));clinicOptions.value.push(...result.items);cursor=result.next_cursor}while(cursor);selectedClinics.value=clinicOptions.value.map(c=>c.id);clinicText.value=selectedClinics.value.join(',');synchronize();preparationBaseline.value=preparationState()}catch(failure){await failed(failure)}await load()})
</script>
<template><section><p class="eyebrow">QUARTERLY PERFORMANCE</p><h1>季度核算工作区</h1><p>准备依据 → 冻结来源计算 → 独立复核发布。自然季度按北京时间，收入按开票时点归实际实施者，成本按发生时点；个人正净利润的 10% 为激励。</p><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div v-if="unknown"><button :disabled="busy" @click="query">查询办理进度</button><button :disabled="busy" @click="execute">重新确认办理结果</button></div>
<fieldset :disabled="busy||unknown"><legend>核算范围</legend><label>自然季度<select v-model="period.quarter_start" @change="changeQuarter"><option v-for="q in quarterOptions" :key="q.value" :value="q.value">{{q.label}}</option></select></label><label>冻结截止（北京时间）<span>{{new Date(period.cutoff).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</span><button type="button" @click="period.cutoff=new Date().toISOString();resetPreparation();stage=1">以当前时间建立新批次</button></label><label class="wide">核算诊所范围<div class="filter-tabs"><label v-for="c in clinicOptions" :key="c.id"><input v-model="selectedClinics" type="checkbox" :value="c.id" @change="clinicText=selectedClinics.join(',');synchronize();stage=1">{{c.label}}</label></div></label><button @click="load()">刷新季度版本</button></fieldset><div class="step-tabs" aria-label="核算步骤"><button v-for="(name,i) in ['资料准备','冻结计算','独立复核','发布结果']" :key="name" :aria-current="stage===i+1?'step':undefined" @click="stage=i+1">{{i+1}} · {{name}}</button></div>
 <div v-if="batches.length" class="surface"><label>继续已有准备批次<select v-model="selectedBatch" @change="bindBatch"><option value="">选择冻结批次</option><option v-for="batch in batches" :key="batch.input_hash" :value="batch.input_hash">{{new Date(batch.cutoff!).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} · {{batch.clinic_ids?.map(id=>clinicOptions.find(c=>c.id===id)?.label??id).join('、')}}</option></select></label></div>
 <form v-if="stage===1 && can('cost.verify')" @submit.prevent="prepare"><h2>1. 核实季度准备</h2><p>系统生成完整人员及来源；诊所选择不能删去人员在其他诊所的收入、成本或有效执业。无记录不等于零成本。</p><fieldset :disabled="busy||unknown" @input="confirmed=false"><label class="wide">人员名单核验依据<input v-model="personnel" required maxlength="255"></label><section v-for="closure in closures" :key="closure.clinic_id" class="closure"><h3>{{clinicOptions.find(c=>c.id===closure.clinic_id)?.label??closure.clinic_id}} · 封账依据</h3><label>封账来源编号<input v-model="closure.source_reference" required maxlength="255"></label><label>封账核验依据<input v-model="closure.verification_reference" required maxlength="255"></label><label><input v-model="closure.zero_cost_scope" type="checkbox" value="MEDICAL_SUPPLY">已确认医疗用品零成本范围（须有已核实零额凭证）</label><label><input v-model="closure.zero_cost_scope" type="checkbox" value="OPERATING">已确认运营零成本范围（须有已核实零额凭证）</label></section></fieldset><label><input v-model="confirmed" type="checkbox" required :disabled="busy||unknown">已核对完整人员、来源、封账及零成本范围</label><button :disabled="busy||unknown||!confirmed||!closures.length">保存季度准备</button></form>
<form v-if="stage===2 && can('performance.calculate')" @submit.prevent="calculate"><h2>2. 按冻结依据计算</h2><fieldset :disabled="busy||unknown"><div class="confirmation-summary wide"><strong>{{preparationText?'已绑定同一冻结批次':'尚未绑定准备批次'}}</strong><p>季度 {{period.quarter_start}} 至 {{period.quarter_end}}（不含）</p><p>系统会传递本批全部准备凭据，无需复制内部编号。</p><details v-if="preparationText"><summary>批次标识</summary>{{preparationText}}</details></div><button :disabled="!clinicText.trim()||!preparationText">计算季度绩效</button></fieldset><p>交接时可从“继续已有准备批次”选择同一批次。新来源需以新截止重新核实准备；旧快照只读保留。</p></form>
<section v-if="stage===3 && can('performance.publish')" class="surface"><h2>3. 独立复核发布</h2><p>获授发布能力的人员须单独核对来源、人员、分摊及 R1；计算和复核发布是独立操作。</p><label>独立复核依据<input v-model="reviewReference" maxlength="255" :disabled="busy||unknown" @input="reviewed=[]"></label></section>
<div class="table-scroll"><table class="performance-table"><caption>人员及计算版本（未定金额显示 —）</caption><thead><tr><th>牙医／版本</th><th>状态</th><th>收入</th><th>医疗用品</th><th>运营费用</th><th>净利润</th><th>激励</th><th>缺项／操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.quarterly_performance_id" :data-dentist="row.dentist_id" :data-performance="row.quarterly_performance_id" :data-status="row.calculation_status"><td>{{row.dentist_id}} / v{{row.calculation_version}}<small>凭据 {{row.quarterly_performance_id}}</small></td><td>{{statusName[row.calculation_status]}}</td><td>{{row.revenue??'—'}}</td><td>{{row.medical_supply_cost??'—'}}</td><td>{{row.operating_expense??'—'}}</td><td>{{row.net_profit??'—'}}</td><td>{{row.incentive_amount??'—'}}<small>率 {{row.incentive_rate}}</small></td><td><ul><li v-for="reason in row.incomplete_reasons" :key="reason">{{missingReason(reason)}}<details><summary>核验标识</summary>{{reason}}</details><RouterLink to="/cost-entries">去核验来源 →</RouterLink></li></ul><button v-if="sourceAllowed" :disabled="busy||unknown" @click="source(row)">核对冻结来源</button><template v-if="can('performance.publish') && row.calculation_status==='CALCULATED'"><label><input v-model="reviewed" type="checkbox" :value="row.quarterly_performance_id" :disabled="busy||unknown">已核实本版本</label><button :disabled="busy||unknown||!reviewReference.trim()||!reviewed.includes(row.quarterly_performance_id)" @click="publish(row)">复核并发布本版本</button></template></td></tr></tbody></table></div><p v-if="!items.length&&!busy&&!error" class="empty-state">本季度暂无核算版本，可先核实资料并保存准备。</p><button v-if="next" :disabled="busy||unknown" @click="load(true)">更多季度版本</button>
<section v-if="sources" class="source-panel"><h2>冻结来源与分摊依据</h2><p>规则 {{sources.rule_version}} · 截止 {{sources.cutoff}}</p><p class="hash">输入摘要 {{sources.input_hash}}</p><template v-if="snapshot"><h3>核实的人员范围</h3><table><thead><tr><th>牙医</th><th>入职日</th><th>离职日（含）</th></tr></thead><tbody><tr v-for="person in snapshot.input.personnel" :key="person.id"><td>{{person.id}}</td><td>{{person.hire}}</td><td>{{person.termination??'—'}}</td></tr></tbody></table><h3>收入来源（开票快照）</h3><table><thead><tr><th>结算明细</th><th>实际实施者</th><th>诊所</th><th>开票时点</th><th>金额</th></tr></thead><tbody><tr v-for="row in snapshot.input.revenue" :key="row.item"><td>{{row.item}}</td><td>{{row.dentist}}</td><td>{{row.clinic}}</td><td>{{row.issued}}</td><td>{{row.amount}}</td></tr></tbody></table><h3>已确认成本来源</h3><table><thead><tr><th>来源编号／凭证</th><th>归属牙医</th><th>类型</th><th>实际发生时点</th><th>金额</th></tr></thead><tbody><tr v-for="row in snapshot.input.costs" :key="row.id"><td>{{row.source}}<small>{{row.id}}</small></td><td>{{row.dentist??'公共净额'}}</td><td>{{row.type==='MEDICAL_SUPPLY'?'医疗用品':'运营费用'}}</td><td>{{row.incurred}}</td><td>{{row.amount}}</td></tr></tbody></table><h3>公共运营净额分摊</h3><p v-if="!snapshot.allocations.length">本批没有公共运营净额分摊。</p><section v-for="allocation in snapshot.allocations" :key="allocation.clinic_id"><p>诊所 {{allocation.clinic_id}} · 净额 {{allocation.net_amount}}</p><table><thead><tr><th>牙医</th><th>有效正常出诊分钟</th><th>净额份额</th></tr></thead><tbody><tr v-for="share in allocation.recipients" :key="share.dentist_id"><td>{{share.dentist_id}}</td><td>{{share.normal_minutes}}</td><td>{{share.share}}</td></tr></tbody></table></section></template><details><summary>完整冻结核验记录</summary><pre>{{JSON.stringify(sources.source_snapshot,null,2)}}</pre></details><button @click="sources=null">关闭来源明细</button></section></section></template>
<style scoped>fieldset{display:flex;gap:16px;flex-wrap:wrap;padding:20px;margin:20px 0}label{display:grid;gap:6px;min-width:180px}label:has([type=checkbox]){display:flex;min-width:0;margin:12px 0}input{padding:9px;border:1px solid #bacdc5;border-radius:5px}.wide{flex:1 1 100%}.closure{background:#f5f9f7;padding:16px;flex:1;min-width:260px}.closure label{margin-bottom:12px}button{padding:9px 14px;margin:4px}table{font-size:13px;width:100%;border-collapse:collapse}th,td{padding:12px 9px;border-bottom:1px solid #dce7e2;text-align:left;vertical-align:top}th{background:#f5f9f7;white-space:nowrap}.performance-table td:nth-child(n+3):nth-child(-n+7){text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.performance-table small{max-width:160px;word-break:break-all}small{display:block;color:#56675e;overflow-wrap:anywhere}pre{max-height:500px;overflow:auto;background:#f5f9f7;padding:16px;font-size:12px}.source-panel{margin-top:24px;padding:20px;border:1px solid #bacdc5}.hash{overflow-wrap:anywhere}</style>
